# AI Office v2.3 Part C Dashboard Integration Certification Release Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found at E:\AI\AI-Office" }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.3-part-c-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @(
 "config\conversational-office",
 "workspace\conversational-office\certifications",
 "dashboard\public\data",
 "scripts\conversational-office",
 "docs"
)) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $BackupPath = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $BackupPath
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\conversational-office\release-manifest.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\New-AIOfficeConversationDashboardSnapshot.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\conversational-office-module.js" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\conversational-office-module.css" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Install-AIOfficeConversationDashboardIntegration.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Test-AIOfficeConversationDashboard.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Certify-AIOfficeConversationalOffice.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Publish-AIOfficeConversationalOfficeRelease.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Test-AIOfficeConversationalOffice.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.3-Release-Notes.md" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.3-Part-C-Dashboard-Integration-Certification-Release.md" -Base64Content ""
$ScriptPaths = @(
 "E:\AI\AI-Office\scripts\conversational-office\New-AIOfficeConversationDashboardSnapshot.ps1",
 "E:\AI\AI-Office\scripts\conversational-office\Install-AIOfficeConversationDashboardIntegration.ps1",
 "E:\AI\AI-Office\scripts\conversational-office\Test-AIOfficeConversationDashboard.ps1",
 "E:\AI\AI-Office\scripts\conversational-office\Certify-AIOfficeConversationalOffice.ps1",
 "E:\AI\AI-Office\scripts\conversational-office\Publish-AIOfficeConversationalOfficeRelease.ps1",
 "E:\AI\AI-Office\scripts\conversational-office\Test-AIOfficeConversationalOffice.ps1"
)
foreach ($ScriptPath in $ScriptPaths) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $ScriptPath + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; ")) }
}
& "E:\AI\AI-Office\scripts\conversational-office\New-AIOfficeConversationDashboardSnapshot.ps1" | Out-Null
& "E:\AI\AI-Office\scripts\conversational-office\Install-AIOfficeConversationDashboardIntegration.ps1"
& "E:\AI\AI-Office\scripts\conversational-office\Test-AIOfficeConversationDashboard.ps1" | Out-Null
Write-Host ""
Write-Host "AI Office v2.3 Part C Dashboard Integration, Certification and Release installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan